    "isAnulada": false,
    "statement": "Paciente de 23 anos de idade, sem vida sexual ativa e com história prévia de ciclos menstruais irregulares (a cada 3 ou 4 meses) com fluxo intenso. Tem sobrepeso e hirsutismo. Foi orientada mudança no estilo de vida, após perda de 5% do peso inicial, os ciclos menstruais regularam, mas o hirsutismo manteve-se moderado. Foi fechado diagnóstico de síndrome dos ovários policísticos, após exclusão de outras causas de hiperandrogenismo. Visando o tratamento do hirsutismo a conduta adequada com a respectiva justificativa é:",
