    "isAnulada": false,
    "statement": "Com relação à Síndrome dos Ovários Policísticos – SOP –, analise as afirmativas abaixo. I. A SOP é considerada um diagnóstico de exclusão. Para tanto, incluem-se entre os diagnósticos diferenciais o hipotireoidismo, a hiperprolactinemia, a hiperplasia adrenal congênita forma tardia e a síndrome de Cushing. II. O perfil lipídico clássico observado em mulheres com SOP se caracteriza por aumento da razão entre colesterol total e HDL e níveis reduzido de HDL. III. A metformina, uma das drogas utilizadas para SOP, reduz os níveis séricos de insulina, aumentando a gliconeogênese hepática. IV. A espironolactona, agente antiandrogênico, tem sua ação realizada através da inibição da 5α-redutase, afetando a conversão do pelo velus em terminal.V. Os níveis séricos elevados de Sulfato de Deidroepiandrosterona - SDHEA > 700μg/dl sugerem a presença de neoplasia ovariana e os níveis elevados de 17OH progesterona sugerem deficiência da enzima 21- hidroxilase, hiperplasia adrenal congênita forma tardia. Estão CORRETAS as afirmativas.",
