    "statement": "Paciente, 32 anos, sexo feminino, diagnosticada com Síndrome dos Ovários Policísticos (SOP), deseja engravidar e é indicada para tratamento com indutores de ovulação. A escolha do tratamento é o Citrato de Clomifeno (CC). Sobre o mecanismo de ação e os efeitos colaterais potenciais do Citrato de Clomifeno, é CORRETO afirmar:",
