    "statement": "Uma paciente de 12 anos de idade vai a consulta agendada em Unidade de Saúde da Família acompanhada pela mãe. A familiar demonstra preocupações quanto ao desenvolvimento da filha, alegando ser esta uma das mais baixas entre as respectivas colegas e que ainda não teve a primeira menstruação, a despeito de estar notando desenvolvimento das mamas há 10 meses, observando-se a presença de broto mamário ao exame físico. Refere-se, também, que a mãe está receosa de a filha vir a ser diagnosticada com síndrome dos ovários policísticos (SOP), tendo base tal preocupação em leitura de informações da internet em correlação com o fato de a filha apresentar acne facial, de ainda nunca ter menstruado e de possuir histórico familiar de primeiro grau de obesidade e diabetes mellitus tipo 2. Faz uso de metilfenidato 10 mg/dia por diagnóstico prévio de transtorno de deficit de atenção e hiperatividade, demonstrando manter atenção apenas para atividades do próprio interesse, sem, no entanto, apresentar histórico de baixo desempenho escolar ou prejuízo da vida social. Em avaliação ponderoestatural, verifica-se IMC de 21 kg/m², considerado adequado para a idade da paciente. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A acne citada pela mãe da paciente na consulta é um achado dermatológico pouco específico para SOP, embora aumente a probabilidade pré-teste para hiperandrogenismo, componente da fisiopatologia de SOP.",
