    "statement": "A.S.M., 26 anos, solteira, estudante de pós-graduação, consulta com queixa de irregularidade menstrual e ganho de peso. Menarca aos 13 anos com ciclos irregulares desde então. Atualmente, menstrua a cada 45-90 dias, com fluxo variável. Refere ganho de 15 kg nos últimos 3 anos (peso atual: 78 kg; altura: 1,62 m; IMC: 29,7 kg/m²). Queixa-se de aumento de pelos no rosto (necessita depi- lar buço semanalmente), acne facial moderada e queda de cabelo. Nega galactorreia, cefaleia, alterações visuais ou sintomas de hiper/hipotireoidismo. Não está em relacionamento, mas deseja engravidar no futuro. Nega uso de medicações. Mãe diabética tipo 2 (diagnosticada aos 50 anos) e hipertensa. Nega tabagismo. Exame físico: PA: 130x85 mmHg; FC: 78 bpm. Acantose nigricans em região cervical posterior e axilas. Acne inflamatória em face. Hirsutismo (Escala de FerrimanGallwey: 14 pontos; pelos em face, tórax, linha alba). Mamas sem alterações, sem galactorreia. Abdome: tecido adiposo aumentado com distribuição central. Exame ginecológico: sem particularidades ao especular e toque bimanual. Exames trazidos pela paciente (colhidos no 3º dia de amenorreia, após menstruação espontânea há 5 dias): \n•  Glicemia jejum: 102 mg/dL; \n•  Insulina jejum: 28 μUI/mL (VR: 2-25 μUI/mL); \n•  HOMA-IR: 7,0 (VR:  12 folículos de 2-9 mm dispostos em “colar de pérolas”); o Ovário esquerdo aumentado (10 cm³), com padrão morfológico semelhante. Baseando-se nos Critérios de Rotterdam (2003) e nas diretrizes atuais para diagnóstico e manejo, qual a interpretação diagnóstica mais adequada e a primeira conduta terapêutica indicada?",
